sed -i '/public void applyToJobPosting/i \    @Transactional(readOnly = true)\n    public java.util.List<org.example.comprova.dto.QuestionDTO> getApplicationTestQuestions(Long applicationId, Candidate candidate) {\n        JobApplication app = jobApplicationRepository.findById(applicationId)\n                .orElseThrow(() -> new RuntimeException("Application not found"));\n        if (!app.getCandidate().getId().equals(candidate.getId())) throw new RuntimeException("Forbidden");\n        return app.getJobPosting().getQuestions().stream().map(q -> new org.example.comprova.dto.QuestionDTO(\n                q.getStatement(), q.getType().name(), q.getSkillEvaluated(), q.getEstimatedTimeMinutes(), null, q.getCodeSnippet(), q.getEvaluationCriteria()\n        )).toList();\n    }\n' comprova-backend/src/main/java/org/example/comprova/service/JobPostingService.java
